-- Objects that no migration in this repository creates (made live by hand),
-- and objects a migration creates that live has since dropped.
do $$
begin
  if to_regclass('public.godspeed_api_usage') is not null then
    execute 'grant insert, select, update, delete, truncate, references, trigger on table public.godspeed_api_usage to anon, authenticated, service_role';
  end if;
end
$$;

